contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v, address a, address b) public payable {
        require(b != address(0));

        c.SetMinSum(v); if (__ESBMC_reverted()) return;
        uint afterSetMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetLogFile(a); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool minReverted;
        c.SetMinSum(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { minReverted = true; } else { minReverted = false; }

        bool logReverted;
        c.SetLogFile(b); bool __rev1 = __ESBMC_reverted(); if (__rev1) { logReverted = true; } else { logReverted = false; }

        assert(afterSetMinSum == v && c.MinSum() == v && minReverted && logReverted);
    }
}

